diff --git a/web/app/globals.css b/web/app/globals.css
index ee96307..71d4223 100644
--- a/web/app/globals.css
+++ b/web/app/globals.css
@@ -183,3 +183,39 @@
 @theme static {
   --breakpoint-sm: 40rem;
 }
+
+/* #922 prototype, never merged: the most repeated class lists of a word page as
+   one short utility each, built from the same utilities they listed. */
+@utility form-link {
+  @apply cursor-pointer font-mono text-text-strong no-underline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent;
+}
+@utility tense-cell {
+  @apply p-0 pr-4 align-baseline font-mono text-[0.875rem] leading-[1.625rem] text-text-strong sm:wrap-anywhere sm:text-[0.9375rem] sm:leading-[1.8125rem];
+}
+@utility tense-cell-row {
+  @apply p-0 pr-4 align-baseline font-mono text-[0.875rem] leading-[1.625rem] text-text-strong sm:wrap-anywhere sm:text-[0.9375rem] sm:leading-[1.8125rem] py-px;
+}
+@utility tense-cell-row-wide {
+  @apply p-0 pr-4 align-baseline font-mono text-[0.875rem] leading-[1.625rem] text-text-strong sm:wrap-anywhere sm:text-[0.9375rem] sm:leading-[1.8125rem] sm:py-px;
+}
+@utility person {
+  @apply p-0 pr-3 align-baseline whitespace-nowrap font-sans text-[0.75rem] leading-6 sm:text-[0.8rem] sm:leading-[1.5625rem] font-normal text-text-muted;
+}
+@utility person-hit {
+  @apply p-0 pr-3 align-baseline whitespace-nowrap font-sans text-[0.75rem] leading-6 sm:text-[0.8rem] sm:leading-[1.5625rem] font-semibold text-accent;
+}
+@utility word-rest {
+  @apply hidden items-baseline gap-3 group-data-open/words:flex group-data-measuring/words:flex;
+}
+@utility word-text {
+  @apply font-serif text-[1.1rem] text-text-strong;
+}
+@utility word-dot {
+  @apply font-sans text-[0.75rem] text-text-muted;
+}
+@utility expr-row-extra {
+  @apply hidden gap-x-4 gap-y-1 max-sm:flex-col sm:items-baseline group-data-open/expressions:sm:grid-cols-[11.875rem_minmax(0,1fr)] group-data-open/expressions:max-sm:flex group-data-open/expressions:sm:grid;
+}
+@utility expr-phrase {
+  @apply font-serif text-[1.0625rem] leading-snug max-w-full shrink-0 text-text wrap-anywhere;
+}
